/**
 * Fixed credits facts. Names of products, fonts and people are not translated; every sentence
 * around them lives in the i18n catalogs under `ui.credits.*`.
 */

/** Served next to index.html; generated by scripts/generate-third-party-notices.mjs. */
export const THIRD_PARTY_NOTICES_URL = './THIRD_PARTY_NOTICES.txt';

/**
 * Privacy page of the browser demo. Only the demo repository carries it
 * (scripts/deploy/demo-repo/, copied by scripts/deploy-pages.mjs), so only web builds link it.
 */
export const PRIVACY_URL = './datenschutz.html';

export const CREDITS_DEVELOPER = 'NeMe';

export interface CreditsEntry {
  readonly name: string;
  /** Translation key of the role or license line shown below the name. */
  readonly detailKey: string;
}

export const CREDITS_TOOLS: readonly CreditsEntry[] = [
  { name: 'Phaser', detailKey: 'ui.credits.tools.phaser' },
  { name: 'PeerJS', detailKey: 'ui.credits.tools.peerjs' },
  { name: 'valibot', detailKey: 'ui.credits.tools.valibot' },
];

export const CREDITS_FONTS: readonly CreditsEntry[] = [
  { name: 'Chakra Petch', detailKey: 'ui.credits.fonts.ofl' },
  { name: 'JetBrains Mono', detailKey: 'ui.credits.fonts.ofl' },
];

/** Every translation key the credits dialog renders; the catalogs must provide all of them. */
export const CREDITS_TRANSLATION_KEYS: readonly string[] = [
  'ui.options.credits',
  'ui.credits.title',
  'ui.credits.game.heading',
  'ui.credits.game.developer',
  'ui.credits.game.version',
  'ui.credits.tools.heading',
  'ui.credits.fonts.heading',
  'ui.credits.ai.heading',
  'ui.credits.ai.body',
  'ui.credits.licenses.heading',
  'ui.credits.licenses.body',
  'ui.credits.licenses.show',
  'ui.credits.licenses.hide',
  'ui.credits.licenses.loading',
  'ui.credits.licenses.failed',
  'ui.credits.close',
  'ui.credits.privacy',
  ...new Set([...CREDITS_TOOLS, ...CREDITS_FONTS].map(entry => entry.detailKey)),
];
